    try {
      AudioFormat format = new AudioFormat(
          44100, // sample rate
          16, // bits per sample
          2, // channels
          true, // signed samples
          false); // mono

      DataLine.Info info = new DataLine.Info(TargetDataLine.class, format);
      TargetDataLine line = (TargetDataLine) AudioSystem.getLine(info);
      line.open(format);

