      Line.Info info2 = new Line.Info(SourceDataLine.class, format);
      SourceDataLine line2 = (SourceDataLine) AudioSystem.getLine(info2);
      line2.open(format);

      format = new AudioFormat(
          44100, // sample rate
          16, // bits per sample
          2, // channels
          true, // signed samples
          false); // mono

      DataLine.Info info3 = new DataLine.Info(TargetDataLine.class, format);
      TargetDataLine line3 = (TargetDataLine) AudioSystem.getLine(info3);
      line3.open(format);

      Thread.sleep(5000);

      line.start();
      line2.start();
      line3.start();

      while (true) {
        line.write("bird".getBytes(), 0, "bird".length());
        line2.write("rustle".getBytes(), 0, "rustle".length());
        line3.write("cicada".getBytes(), 0, "cicada".length());

        Thread.sleep(1000);
      }
    } catch (Exception e) {
      e.printStackTrace();
    }
  }
}
```

